ill-change:transform;\\n}\\n\\n.beauty-panel:hover::before{\\n    transform:scale(1.06);\\n}\\n\\n.beauty-panel::after{\\n    content:\\\"\\\";\\n    position:absolute;\\n    inset:0;\\n    z-index:1;\\n    transition:opacity .4s ease;\\n}\\n\\n.beauty-panel:not(.active)::after{\\n    background:rgba(0,0,0,.28);\\n    opacity:1;\\n}\\n\\n.beauty-panel.active::after{\\n    background:transparent;\\n    opacity:0;\\n}\\n\\n.beauty-dots{\\n    display:none;\\n}\\n\\n\\/* =========================\\n   MOBILE SLIDER\\n========================= *\\/\\n\\n@media (max-width:767px){\\n\\n    .beauty-panels{\\n        display:flex;\\n        flex-direction:row;\\n        overflow-x:auto;\\n        overflow-y:hidden;\\n        height:auto;\\n        gap:14px;\\n        padding-bottom:8px;\\n\\n        scroll-snap-type:x mandatory;\\n        -webkit-overflow-scrolling:touch;\\n        scrollbar-width:none;\\n    }\\n\\n    .beauty-panels::-webkit-scrollbar{\\n        display:none;\\n    }\\n\\n    .beauty-panel{\\n        flex:0 0 88%;\\n        width:88%;\\n        height:380px;\\n        min-width:88%;\\n        border-radius:24px;\\n        scroll-snap-align:center;\\n        transform:none !important;\\n    }\\n\\n    .beauty-panel::before{\\n        transform:none !important;\\n    }\\n\\n    .beauty-panel::after{\\n        background:transparent !important;\\n        opacity:0 !important;\\n    }\\n\\n    .beauty-panel.active{\\n        flex:0 0 88%;\\n    }\\n\\n    .beauty-dots{\\n        display:flex;\\n        justify-content:center;\\n        gap:8px;\\n        margin-top:16px;\\n    }\\n\\n    .beauty-dot{\\n        width:8px;\\n        height:8px;\\n        border-radius:50%;\\n        background:#d5d5d5;\\n        transition:.3s ease;\\n    }\\n\\n    .beauty-dot.active{\\n        transform:scale(1.3);\\n        background:#111;\\n    }\\n}\\n<\\/style>\\n\\n<script>\\ndocument.addEventListener(\'DOMContentLoaded\', function () {\\n\\n    const panels = document.querySelectorAll(\'.beauty-panel\');\\n\\n    \\/\\/ \\u062f\\u0633\\u06a9\\u062a\\u0627\\u067e: \\u0647\\u0645\\u0648\\u0646 \\u0631\\u0641\\u062a\\u0627\\u0631 \\u0642\\u0628\\u0644\\u06cc\\n    panels.forEach(panel => {\\n        panel.addEventListener(\'click\', function () {\\n\\n            if (window.innerWidth <= 767) return;\\n\\n            if (this.classList.contains(\'active\')) return;\\n\\n            panels.forEach(p => p.classList.remove(\'active\'));\\n            this.classList.add(\'active\');\\n        });\\n    });\\n\\n    \\/\\/ \\u0645\\u0648\\u0628\\u0627\\u06cc\\u0644: dots + active slide\\n    const slider = document.querySelector(\'.beauty-panels\');\\n    const dotsContainer = document.querySelector(\'.beauty-dots\');\\n\\n    if (slider && window.innerWidth <= 767) {\\n\\n        const slides = [...slider.querySelectorAll(\'.beauty-panel\')];\\n\\n        slides.forEach((_, index) => {\\n            const dot = document.createElement(\'div\');\\n            dot.className = \'beauty-dot\';\\n\\n            if(index === 0){\\n                dot.classList.add(\'active\');\\n            }\\n\\n            dot.addEventListener(\'click\', () => {\\n                slider.scrollTo({\\n                    left: slides[index].offsetLeft - 10,\\n                    behavior: \'smooth\'\\n                });\\n            });\\n\\n            dotsContainer.appendChild(dot);\\n        });\\n\\n        const dots = [...dotsContainer.children];\\n\\n        function updateDots(){\\n            const sliderCenter =\\n                slider.scrollLeft + (slider.offsetWidth \\/ 2);\\n\\n            let activeIndex = 0;\\n            let closest = Infinity;\\n\\n            slides.forEach((slide, index) => {\\n\\n                const center =\\n                    slide.offsetLeft + (slide.offsetWidth \\/ 2);\\n\\n                const diff =\\n                    Math.abs(sliderCenter - center);\\n\\n                if(diff < closest){\\n                    closest = diff;\\n                    activeIndex = index;\\n                }\\n            });\\n\\n            dots.forEach(dot =>\\n                dot.classList.remove(\'active\')\\n            );\\n\\n            dots[activeIndex]?.classList.add(\'active\');\\n        }\\n\\n        slider.addEventListener(\'scroll\', updateDots);\\n        updateDots();\\n    }\\n\\n});\\n<\\/script>\",\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"4b9ca0c\",\"elType\":\"e-flexbox\",\"settings\":{\"classes\":{\"$$type\":\"classes\",\"value\":[\"e-86b5cf2\"]}},\"elements\":[{\"id\":\"fa65dff\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[beauty_ui_login]\",\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":false,\"styles\":{\"e-86b5cf2\":{\"id\":\"e-86b5cf2\",\"label\":\"local\",\"type\":\"class\",\"variants\":[{\"meta\":{\"breakpoint\":\"desktop\",\"state\":null},\"props\":{\"flex-direction\":{\"$$type\":\"string\",\"value\":\"row\"}},\"custom_css\":null}]}},\"interactions\":[],\"editor_settings\":[],\"version\":\"0.0\"}]'),(7248,359,'_elementor_used_global_class','e-59e63fa-7f314d5'),(7249,359,'_elementor_used_global_class_preview','e-59e63fa-7f314d5'),(7250,360,'_elementor_edit_mode','builder'),(7251,360,'_elementor_template_type','wp-page'),(7252,360,'_elementor_version','4.1.1'),(7253,360,'_elementor_pro_version','4.1.0'),(7254,360,'_elementor_global_class_usage_indexed','1'),(7255,360,'_elementor_global_class_usage_indexed_preview','1'),(7256,360,'_elementor_migrations_state_d2a1','4.1.1:4.1.0:997ef14e505ddd4af49c620835e30da6'),(7257,360,'_wp_page_template','elementor_header_footer'),(7258,360,'_elementor_data','[{\"id\":\"d5656c4\",\"elType\":\"container\",\"settings\":{\"container_type\":\"grid\",\"grid_columns_grid\":{\"unit\":\"fr\",\"size\":2},\"grid_rows_grid\":{\"unit\":\"fr\",\"size\":\"1\"},\"grid_rows_grid_mobile\":{\"unit\":\"fr\",\"size\":1},\"content_width\":\"full\",\"min_hei