\":\"local\",\"type\":\"class\",\"variants\":[{\"meta\":{\"breakpoint\":\"desktop\",\"state\":null},\"props\":{\"padding\":{\"$$type\":\"size\",\"value\":{\"size\":0,\"unit\":\"px\"}},\"display\":{\"$$type\":\"string\",\"value\":\"flex\"},\"flex-direction\":{\"$$type\":\"string\",\"value\":\"column\"},\"gap\":{\"$$type\":\"size\",\"value\":{\"size\":44,\"unit\":\"px\"}},\"justify-content\":{\"$$type\":\"string\",\"value\":\"center\"},\"align-items\":{\"$$type\":\"string\",\"value\":\"center\"}},\"custom_css\":null}]}},\"interactions\":[],\"editor_settings\":[],\"version\":\"0.0\"},{\"id\":\"a8ca442\",\"elType\":\"widget\",\"settings\":{\"html\":\"<div class=\\\"beauty-wrapper\\\">\\n\\n    <div class=\\\"beauty-panels\\\">\\n\\n        <div class=\\\"beauty-panel active\\\" style=\\\"background-image:url(\'https:\\/\\/arayeshilatifi.ir\\/wp-content\\/uploads\\/2026\\/06\\/IMG_1611.jpeg\');\\\"><\\/div>\\n\\n        <div class=\\\"beauty-panel\\\" style=\\\"background-image:url(\'https:\\/\\/arayeshilatifi.ir\\/wp-content\\/uploads\\/2026\\/06\\/IMG_1981.jpeg\');\\\"><\\/div>\\n\\n        <div class=\\\"beauty-panel\\\" style=\\\"background-image:url(\'https:\\/\\/arayeshilatifi.ir\\/wp-content\\/uploads\\/2026\\/06\\/IMG_3434.jpeg\');\\\"><\\/div>\\n\\n    <\\/div>\\n\\n    <div class=\\\"beauty-dots\\\"><\\/div>\\n\\n<\\/div>\\n\\n<style>\\n.beauty-wrapper{\\n    width:100%;\\n}\\n\\n\\/* =========================\\n   DESKTOP (\\u0647\\u0645\\u0648\\u0646 \\u0642\\u0628\\u0644\\u06cc)\\n========================= *\\/\\n\\n.beauty-panels{\\n    display:flex;\\n    gap:18px;\\n    width:100%;\\n    height:620px;\\n    overflow:hidden;\\n}\\n\\n.beauty-panel{\\n    position:relative;\\n    flex:0 0 120px;\\n    border-radius:24px;\\n    cursor:pointer;\\n    overflow:hidden;\\n    background-size:cover;\\n    background-position:center;\\n    transition:\\n        flex .85s cubic-bezier(.16,1,.3,1),\\n        transform .5s ease;\\n    will-change:flex, transform;\\n    -webkit-tap-highlight-color:transparent;\\n}\\n\\n.beauty-panel.active{\\n    flex:1;\\n}\\n\\n.beauty-panel:hover{\\n    transform:translateY(-3px);\\n}\\n\\n.beauty-panel::before{\\n    content:\\\"\\\";\\n    position:absolute;\\n    inset:0;\\n    background:inherit;\\n    background-size:cover;\\n    background-position:center;\\n    transition:transform 1s cubic-bezier(.16,1,.3,1);\\n    will-change:transform;\\n}\\n\\n.beauty-panel:hover::before{\\n    transform:scale(1.06);\\n}\\n\\n.beauty-panel::after{\\n    content:\\\"\\\";\\n    position:absolute;\\n    inset:0;\\n    z-index:1;\\n    transition:opacity .4s ease;\\n}\\n\\n.beauty-panel:not(.active)::after{\\n    background:rgba(0,0,0,.28);\\n    opacity:1;\\n}\\n\\n.beauty-panel.active::after{\\n    background:transparent;\\n    opacity:0;\\n}\\n\\n.beauty-dots{\\n    display:none;\\n}\\n\\n\\/* =========================\\n   MOBILE SLIDER\\n========================= *\\/\\n\\n@media (max-width:767px){\\n\\n    .beauty-panels{\\n        display:flex;\\n        flex-direction:row;\\n        overflow-x:auto;\\n        overflow-y:hidden;\\n        height:auto;\\n        gap:14px;\\n        padding-bottom:8px;\\n\\n        scroll-snap-type:x mandatory;\\n        -webkit-overflow-scrolling:touch;\\n        scrollbar-width:none;\\n    }\\n\\n    .beauty-panels::-webkit-scrollbar{\\n        display:none;\\n    }\\n\\n    .beauty-panel{\\n        flex:0 0 88%;\\n        width:88%;\\n        height:380px;\\n        min-width:88%;\\n        border-radius:24px;\\n        scroll-snap-align:center;\\n        transform:none !important;\\n    }\\n\\n    .beauty-panel::before{\\n        transform:none !important;\\n    }\\n\\n    .beauty-panel::after{\\n        background:transparent !important;\\n        opacity:0 !important;\\n    }\\n\\n    .beauty-panel.active{\\n        flex:0 0 88%;\\n    }\\n\\n    .beauty-dots{\\n        display:flex;\\n        justify-content:center;\\n        gap:8px;\\n        margin-top:16px;\\n    }\\n\\n    .beauty-dot{\\n        width:8px;\\n        height:8px;\\n        border-radius:50%;\\n        background:#d5d5d5;\\n        transition:.3s ease;\\n    }\\n\\n    .beauty-dot.active{\\n        transform:scale(1.3);\\n        background:#111;\\n    }\\n}\\n<\\/style>\\n\\n<script>\\ndocument.addEventListener(\'DOMContentLoaded\', function () {\\n\\n    const panels = document.querySelectorAll(\'.beauty-panel\');\\n\\n    \\/\\/ \\u062f\\u0633\\u06a9\\u062a\\u0627\\u067e: \\u0647\\u0645\\u0648\\u0646 \\u0631\\u0641\\u062a\\u0627\\u0631 \\u0642\\u0628\\u0644\\u06cc\\n    panels.forEach(panel => {\\n        panel.addEventListener(\'click\', function () {\\n\\n            if (window.innerWidth <= 767) return;\\n\\n            if (this.classList.contains(\'active\')) return;\\n\\n            panels.forEach(p => p.classList.remove(\'active\'));\\n            this.classList.add(\'active\');\\n        });\\n    });\\n\\n    \\/\\/ \\u0645\\u0648\\u0628\\u0627\\u06cc\\u0644: dots + active slide\\n    const slider = document.querySelector(\'.beauty-panels\');\\n    const dotsContainer = document.querySelector(\'.beauty-dots\');\\n\\n    if (slider && window.innerWidth <= 767) {\\n\\n        const slides = [...slider.querySelectorAll(\'.beauty-panel\')];\\n\\n        slides.forEach((_, index) => {\\n            const dot = document.createElement(\'div\');\\n            dot.className = \'beauty-dot\';\\n\\n            if(index === 0){\\n                dot.classList.add(\'active\');\\n            }\\n\\n            dot.addEventListener(\'click\', () => {\\n                slider.scrollTo({\\n                    left: slides[index].offsetLeft - 10,\\n                    behavior: \'smooth\'\\n                });\\n            });\\n\\n            dotsContainer.appendChild(dot);\\n        });\\n\\n        const dots = [...dotsContainer.children];\\n\\n        function updateDots(){\\n            const sliderCenter =\\n                slider.scrollLeft + (slider.offsetWidth \\/ 2);\\n\\n            let activeIndex = 0;\\n            let closest = Infinity;\\n\\n            slides.forEach((slide, index) => {\\n\\n                const center =\\n                    slide.offsetLeft + (slide.offsetWidth \\/ 2);\\n\\n                const diff =\\n                    Math.abs(sliderCenter - center);\\n\\n                if(diff < closest){\\n                    closest = diff;\\n                    activeIndex = index;\\n                }\\n            });\\n\\n            dots.forEach(dot =>\\n                dot.classList.remove(\'active\')\\n            );\\n\\n            dots[activeIndex]?.classList.add(\'active\');\\n        }\\n\\n        slider.addEventListener(\'scroll\', updateDots);\\n        updateDots();\\n    }\\n\\n});\\n<\\/script>\",\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"88d77a8\",\"elType\":\"e-flexbox\",\"settings\":{\"classes\":{\"$$type\":\"classes\",\"value\":[\"e-5006381\"]}},\"elements\":[{\"id\":\"f0394b5\",\"elType\":\"widget\",\"settings\":{\"html\":\"<!-- Container \\u0627\\u0635\\u0644\\u06cc \\u0627\\u0633\\u0644\\u0627\\u06cc\\u062f\\u0631 \\u0628\\u0631\\u0646\\u062f\\u0647\\u0627 -->\\n<div class=\\\"brand-grid-container\\\">\\n  <div class=\\\"brand-grid-track\\\">\\n    <!-- \\u0628\\u0631\\u0646\\u062f \\u06f1 -->\\n    <div class=\\\"brand-grid-item\\\">\\n      <img\\n        src=\\\"https:\\/\\/arayeshilatifi.ir\\/wp-content\\/uploads\\/2026\\/07\\/image-4.png\\\"\\n        alt=\\\"Ardene\\\"\\n      \\/>\\n    <\\/div>\\n\\n    <!-- \\u0628\\u0631\\u0646\\u062f \\u06f2 -->\\n    <div class=\\\"brand-grid-item\\\">\\n      <img\\n        src=\\\"https:\\/\\/arayeshilatifi.ir\\/wp-content\\/uploads\\/2026\\/07\\/image-3.png\\\"\\n        alt=\\\"Prime\\\"\\n      \\/>\\n    <\\/div>\\n    <!-- \\u0628\\u0631\\u0646\\u062f \\u06f3 -->\\n    <div class=\\\"brand-grid-item\\\">\\n      <img\\n        src=\\\"https:\\/\\/arayeshilatifi.ir\\