lex !important;\n    align-items:center;\n    justify-content:center;\n    background:#f7f7f7;\n    transition:.25s ease;\n}\n\n.cart-widget-side .close-side-widget a:hover{\n    background:#efefef;\n    transform:rotate(90deg);\n}\n\n.cart-widget-side .wd-action-text{\n    display:none;\n}\n\n/* PRODUCTS WRAPPER */\n.widget_shopping_cart_content{\n    padding:10px 22px 22px;\n}\n\n/* PRODUCT ITEM */\n.elementor-menu-cart__product{\n    display:grid !important;\n    grid-template-columns:82px 1fr auto;\n    gap:14px;\n    align-items:center;\n    padding:18px 0;\n    border-bottom:1px solid rgba(0,0,0,.06);\n}\n\n/* PRODUCT IMAGE */\n.elementor-menu-cart__product-image img{\n    width:82px !important;\n    height:82px !important;\n    object-fit:cover;\n    border-radius:20px;\n    background:#f8f8f8;\n    transition:transform .45s ease;\n}\n\n.elementor-menu-cart__product:hover img{\n    transform:scale(1.04);\n}\n\n/* TITLE */\n.elementor-menu-cart__product-name a{\n    display:block;\n    font-size:15px;\n    font-weight:700;\n    line-height:1.9;\n    color:#111;\n    text-decoration:none;\n    transition:opacity .25s ease;\n}\n\n.elementor-menu-cart__product-name a:hover{\n    opacity:.72;\n}\n\n/* PRICE */\n.elementor-menu-cart__product-price{\n    margin-top:8px;\n    font-size:14px;\n    font-weight:600;\n    color:#666;\n}\n\n.elementor-menu-cart__product-price .amount{\n    color:#111;\n    font-weight:700;\n}\n\n/* REMOVE BTN */\n.elementor-menu-cart__product-remove{\n    align-self:flex-start;\n}\n\n.elementor-menu-cart__product-remove a{\n    width:34px;\n    height:34px;\n    border-radius:50%;\n    background:#f7f7f7;\n    display:flex !important;\n    align-items:center;\n    justify-content:center;\n    text-decoration:none;\n    transition:.25s ease;\n}\n\n.elementor-menu-cart__product-remove a:hover{\n    background:#111;\n    color:#fff !important;\n}\n\n/* SUBTOTAL */\n.elementor-menu-cart__subtotal{\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n    margin-top:22px;\n    padding-top:22px;\n    border-top:1px solid rgba(0,0,0,.06);\n    font-size:15px;\n    font-weight:700;\n    color:#111;\n}\n\n/* FOOTER BUTTONS */\n.elementor-menu-cart__footer-buttons{\n    display:grid;\n    gap:12px;\n    margin-top:22px;\n}\n\n/* BUTTONS */\n.elementor-menu-cart__footer-buttons .elementor-button{\n    width:100%;\n    min-height:54px;\n    border-radius:18px !important;\n    border:none !important;\n    font-size:14px;\n    font-weight:700;\n    transition:.28s ease;\n}\n\n/* VIEW CART */\n.elementor-button--view-cart{\n    background:#f6f6f6 !important;\n    color:#111 !important;\n}\n\n.elementor-button--view-cart:hover{\n    background:#ededed !important;\n}\n\n/* CHECKOUT */\n.elementor-button--checkout{\n    background:#111 !important;\n    color:#fff !important;\n}\n\n.elementor-button--checkout:hover{\n    transform:translateY(-2px);\n    opacity:.92;\n}\n\n/* MOBILE */\n@media(max-width:767px){\n\n    .cart-widget-side{\n        width:100vw !important;\n        max-width:100vw !important;\n        border-radius:24px 24px 0 0 !important;\n    }\n\n    .cart-widget-side .wd-heading{\n        padding:22px 18px 16px;\n    }\n\n    .elementor-menu-cart__product{\n        grid-template-columns:72px 1fr auto;\n        gap:12px;\n        padding:16px 0;\n    }\n\n    .elementor-menu-cart__product-image img{\n        width:72px !important;\n        height:72px !important;\n        border-radius:16px;\n    }\n\n    .elementor-menu-cart__product-name a{\n        font-size:14px;\n    }\n\n    .elementor-menu-cart__footer-buttons .elementor-button{\n        min-height:50px;\n        border-radius:16px !important;\n    }\n}\n\n\n\n#main-header{\n    position:fixed;\n    top:0;\n    left:0;\n    right:0;\n    z-index:99999;\n\n    background:#fff;\n\n    transform:translateY(-100%);\n    transition:\n        transform .35s cubic-bezier(.22,1,.36,1),\n        box-shadow .3s ease;\n}\n\n#main-header.is-sticky{\n    transform:translateY(0);\n    box-shadow:0 10px 35px rgba(0,0,0,.06);\n}\n\nbody{\n    padding-top:90px;\n}\n\n/* =========================\n   Fixed Header Offset\n   ========================= */\n\n/* دسکتاپ / تبلت */\nbody {\n    padding-top: 180px !important;\n}\n\n/* تبلت */\n@media (max-width: 991px) {\n    body {\n        padding-top: 145px !important;\n    }\n}\n\n/* موبایل */\n@media (max-width: 767px) {\n    body {\n        padding-top: 105px !important;\n    }\n}','woodmart-child','','publish','closed','closed','','woodmart-child','','','2026-07-05 22:54:54','2026-07-05 22:54:54','',0,'https://arayeshilatifi.ir/2026/06/08/woodmart-child/',0,'custom_css','',0),(120,1,'2026-06-08 22:30:14','2026-06-08 22:30:14','html,\nbody {\n    direction: rtl !important;\n    text-align: right;\n}\n\nbody {\n    unicode-bidi: embed;\n}','woodmart-child','','inherit','closed','closed','','119-revision-v1','','','2026-06-08 22:30:14','2026-06-08 22:30:14','',119,'https://arayeshilatifi.ir/?p=120',0,'revision','',0),(125,1,'2026-06-09 10:15:04','2026-06-09 10:15:04','html,\nbody {\n    direction: rtl !important;\n    text-align: right;\n}\n\nbody {\n    unicode-bidi: embed;\n}\n\nhtml,\nbody,\nbutton,\ninput,\ntextarea,\nselect,\n.elementor-widget,\n.elementor-heading-title,\n.wd-nav,\n.whb-header,\n.wd-header,\n.woocommerce,\n.woocommerce *,\n.wd-products,\n.wd-product,\n.product,\nbutton,\na {\n    font-family: \"Yekan Bakh\" !important;\n}','woodmart-child','','inherit','closed','closed','','119-revision-v1','','','2026-06-09 10:15:04','2026-06-09 10:15:04','',119,'https://arayeshilatifi.ir/?p=125',0,'revision','',0),(126,1,'2026-06-09 10:15:22','2026-06-09 10:15:22','<link rel=\"stylesheet\" id=\"wd-text-block-css\" href=\"https://arayeshilatifi.ir/wp-content/themes/woodmart/css/parts/el-text-block.css?ver=8.5.0\" type=\"text/css\" media=\"all\" /> 					\n			<p>آرایشی لطیفی ؛ همراه زیبایی شما | خرید محصولات اصل آرایشی و بهداشتی از بندر گناوه</p>\