over;\n    background-position:center;\n    transition:transform 1s cubic-bezier(.16,1,.3,1);\n    will-change:transform;\n}\n.beauty-panel:hover::before{\n    transform:scale(1.06);\n}\n.beauty-panel::after{\n    content:\"\";\n    position:absolute;\n    inset:0;\n    z-index:1;\n    transition:opacity .4s ease;\n}\n.beauty-panel:not(.active)::after{\n    background:rgba(0,0,0,.28);\n    opacity:1;\n}\n.beauty-panel.active::after{\n    background:transparent;\n    opacity:0;\n}\n.beauty-dots{\n    display:none;\n}\n/* =========================\n   MOBILE SLIDER\n========================= */\n@media (max-width:767px){\n    .beauty-panels{\n        display:flex;\n        flex-direction:row;\n        overflow-x:auto;\n        overflow-y:hidden;\n        height:auto;\n        gap:14px;\n        padding-bottom:8px;\n        scroll-snap-type:x mandatory;\n        -webkit-overflow-scrolling:touch;\n        scrollbar-width:none;\n    }\n    .beauty-panels::-webkit-scrollbar{\n        display:none;\n    }\n    .beauty-panel{\n        flex:0 0 88%;\n        width:88%;\n        height:380px;\n        min-width:88%;\n        border-radius:24px;\n        scroll-snap-align:center;\n        transform:none !important;\n    }\n    .beauty-panel::before{\n        transform:none !important;\n    }\n    .beauty-panel::after{\n        background:transparent !important;\n        opacity:0 !important;\n    }\n    .beauty-panel.active{\n        flex:0 0 88%;\n    }\n    .beauty-dots{\n        display:flex;\n        justify-content:center;\n        gap:8px;\n        margin-top:16px;\n    }\n    .beauty-dot{\n        width:8px;\n        height:8px;\n        border-radius:50%;\n        background:#d5d5d5;\n        transition:.3s ease;\n    }\n    .beauty-dot.active{\n        transform:scale(1.3);\n        background:#111;\n    }\n}\n</style>','Home','','inherit','closed','closed','','57-revision-v1','','','2026-06-11 20:06:31','2026-06-11 20:06:31','',57,'https://arayeshilatifi.ir/?p=201',0