/*!40000 ALTER TABLE `wp_snippets` DISABLE KEYS */;
INSERT INTO `wp_snippets` VALUES (1,'Make upload filenames lowercase','Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'sanitize_file_name\', \'mb_strtolower\' );','sample, media','global',0,10,0,'2026-06-11 16:12:55',1,NULL),(2,'Disable admin bar','Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );','sample, admin-bar','front-end',0,10,0,'2026-06-11 16:12:55',1,NULL),(3,'Allow smilies','Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );','sample','global',0,10,0,'2026-06-11 16:12:55',1,NULL),(4,'Current year','Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','<?php echo date( \'Y\' ); ?>','sample, dates','content',0,10,0,'2026-06-11 16:12:55',1,NULL),(5,'Beauty Product Loop','','add_shortcode(\'beauty_product_loop\', function ($atts) {\n    if (!class_exists(\'WooCommerce\')) {\n        return \'\';\n    }\n\n    $atts = shortcode_atts([\n        \'limit\'        => 8,\n        \'columns\'      => 4,\n        \'mobile_width\'  => 86,\n        \'orderby\'      => \'date\',\n        \'order\'        => \'DESC\',\n        \'category\'     => \'\',\n    ], $atts, \'beauty_product_loop\');\n\n    $limit       = absint($atts[\'limit\']);\n    $columns     = max(1, min(6, absint($atts[\'columns\'])));\n    $mobileWidth = max(70, min(95, absint($atts[\'mobile_width\'])));\n    $orderby     = sanitize_text_field($atts[\'orderby\']);\n    $order       = strtoupper(sanitize_text_field($atts[\'order\'])) === \'ASC\' ? \'ASC\' : \'DESC\';\n    $category    = sanitize_text_field($atts[\'category\']);\n\n    $desktopWidth = 100 / ($columns + 0.5);\n\n    $tax_query = [];\n    if (!empty($category)) {\n        $terms = array_map(\'trim\', explode(\',\', $category));\n        $tax_query[] = [\n            \'taxonomy\' => \'product_cat\',\n            \'field\'    => \'slug\',\n            \'terms\'    => $terms,\n        ];\n    }\n\n    $args = [\n        \'post_type\'           => \'product\',\n        \'post_status\'         => \'publish\',\n        \'posts_per_page\'      => $limit,\n        \'orderby\'             => $orderby,\n        \'order\'               => $order,\n        \'ignore_sticky_posts\' => true,\n    ];\n\n    if (!empty($tax_query)) {\n        $args[\'tax_query\'] = $tax_query;\n    }\n\n    $query = new WP_Query($args);\n\n    if (!$query->have_posts()) {\n        return \'\';\n    }\n\n    ob_start();\n    ?>\n    <div class=\"beauty-product-loop\" style=\"--desktop-card-width: <?php echo esc_attr($desktopWidth); ?>%; --mobile-card-width: <?php echo esc_attr($mobileWidth); ?>%;\">\n        <div class=\"beauty-product-track\">\n            <?php\n            while ($query->have_posts()) :\n                $query->the_post();\n\n                $product = wc_get_product(get_the_ID());\n                if (!$product) {\n                    continue;\n                }\n\n                $is_on_sale = $product->is_on_sale();\n                $badge_text = \'\';\n\n                if ($is_on_sale) {\n                    $regular = (float) $product->get_regular_price();\n                    $sale    = (float) $product->get_sale_price();\n\n                    if ($regular > 0 && $sale > 0 && $sale < $regular) {\n                        $percent = round((($regular - $sale) / $regular) * 100);\n                        $badge_text = $percent . \'%\';\n                    } else {\n                        $badge_text = \'تخفیف\';\n                    }\n                }\n\n                $category_name = \'\';\n                $terms = get_the_terms(get_the_ID(), \'product_cat\');\n                if ($terms && !is_wp_error($terms)) {\n                    foreach ($terms as $term) {\n                        if ($term->slug !== \'uncategorized\') {\n                            $category_name = $term->name;\n                            break;\n                        }\n                    }\n                    if (empty($category_name) && !empty($terms[0]->name)) {\n                        $category_name = $terms[0]->name;\n                    }\n                }\n\n                $main_link = get_permalink();\n                ?>\n                <a class=\"beauty-product-card\" href=\"<?php echo esc_url($main_link); ?>\" aria-label=\"<?php echo esc_attr(get_the_title()); ?>\">\n                    <div class=\"beauty-product-media\">\n                        <?php echo $product->get_image(\'woocommerce_thumbnail\', [\'class\' => \'beauty-product-img\']); ?>\n\n                        <?php if ($badge_text) : ?>\n                            <span class=\"beauty-product-badge\"><?php echo esc_html($badge_text); ?></span>\n                        <?php endif; ?>\n                    </div>\n\n                    <div class=\"beauty-product-content\">\n                        <?php if (!empty($category_name)) : ?>\n                            <div class=\"beauty-product-cat\"><?php echo esc_html($category_name); ?></div>\n                        <?php endif; ?>\n\n                        <h3 class=\"beauty-product-title\"><?php echo esc_html(get_the_title()); ?></h3>\n\n                        <div class=\"beauty-product-price\">\n                            <?php echo wp_kses_post($product->get_price_html()); ?>\n                        </div>\n                    </div>\n                </a>\n            <?php endwhile; ?>\n        </div>\n    </div>\n\n    <style>\n        .beauty-product-loop{\n            width:100%;\n            font-family: inherit; /* استفاده از فونت اصلی سایت */\n        }\n\n        .beauty-product-loop,\n        .beauty-product-loop *{\n            box-sizing:border-box;\n        }\n\n        .beauty-product-track{\n            display:flex;\n            gap:0;\n            overflow-x:auto;\n            overflow-y:hidden;\n            scrollbar-width:none;\n            -webkit-overflow-scrolling:touch;\n            scroll-snap-type:x proximity;\n            width:100%;\n        }\n\n        .beauty-product-track::-webkit-scrollbar{\n            display:none;\n        }\n\n        .beauty-product-card{\n            position:relative;\n            display:block;\n            text-decoration:none !important;\n            color:inherit;\n            background:#fff;\n            overflow:hidden;\n            flex:0 0 var(--desktop-card-width);\n            min-width:var(--desktop-card-width);\n            scroll-snap-align:start;\n            border-left:1px solid rgba(0,0,0,.06);\n            border-radius:0;\n            box-shadow:none;\n            transition:transform .35s ease;\n            font-family:inherit;\n        }\n\n        .beauty-product-card:first-child{\n            border-left:0;\n        }\n\n        .beauty-product-media{\n            position:relative;\n            aspect-ratio:1 / 1;\n            overflow:hidden;\n            background:#ffffff; /* تغییر به سفید */\n            border-radius:0;\n            z-index:0;\n            padding:20%; /* کوچک کردن عکس */\n            display:flex;\n            align-items:center;\n            justify-content:center;\n        }\n\n        .beauty-product-img{\n            width:100%;\n            height:100%;\n            object-fit:contain; /* فیت شدن عکس بجای پر کردن باکس */\n            display:block;\n            transform:scale(1);\n            transition:transform .6s cubic-bezier(.16,1,.3,1);\n        }\n\n        .beauty-product-card:hover .beauty-product-img{\n            transform:scale(1.06);\n        }\n\n        .beauty-product-content{\n            position:relative;\n            z-index:2;\n            padding:14px 12px 16px;\n            text-align:right;\n            font-family:inherit;\n        }\n\n        .beauty-product-cat{\n            display:inline-flex;\n            align-items:center;\n            justify-content:center;\n            margin-bottom:8px;\n            padding:4px 8px;\n            border-radius:999px;\n            background:rgba(0,0,0,.04);\n            color:#7a7a7a;\n            font-size:10px;\n            line-height:1.4;\n            font-weight:500;\n            letter-spacing:.1px;\n            font-family:inherit;\n        }\n\n        .beauty-product-title{\n            margin:0 0 10px; /* فاصله از پایین */\n            font-size:14px; /* تغییر به 14 */\n            line-height:1.65;\n            font-weight:inherit; /* فونت دیفالت سایت */\n            color:#111;\n            font-family:inherit;\n            display:-webkit-box;\n            -webkit-line-clamp:2;\n            -webkit-box-orient:vertical;\n            overflow:hidden;\n            min-height:46px;\n        }\n\n        .beauty-product-price{\n            font-size:14px; /* تغییر به 14 */\n            line-height:1.4;\n            font-weight:700; /* سمی بلد */\n            color:#C13383 !important; /* رنگ درخواستی */\n            font-family:inherit;\n            margin-top:10px; /* فاصله بین تایتل و قیمت */\n        }\n\n        .beauty-product-price,\n        .beauty-product-price *{\n            color:#C13383 !important;\n            font-family:inherit;\n            font-size:14px !important;\n        }\n\n        .beauty-product-price del{\n            opacity:.55;\n            margin-inline-end:6px;\n            font-size:12px;\n            font-weight:400;\n            color:#111 !important; /* قیمت قدیمی مشکی بماند */\n        }\n\n        .beauty-product-price ins{\n            text-decoration:none;\n            font-weight:700;\n        }\n\n        .beauty-product-badge{\n            position:absolute;\n            top:12px;\n            right:12px;\n            z-index:2;\n            display:inline-flex;\n            align-items:center;\n            justify-content:center;\n            min-width:44px;\n            height:28px;\n            padding:0 10px;\n            border-radius:999px;\n            background:#111;\n            color:#fff;\n            font-size:12px;\n            font-weight:700;\n            letter-spacing:.2px;\n            font-family:inherit;\n        }\n\n        @media (max-width:767px){\n            .beauty-product-track{\n                padding-inline:16px;\n            }\n\n            .beauty-product-card{\n                flex:0 0 var(--mobile-card-width);\n                min-width:var(--mobile-card-width);\n            }\n\n            .beauty-product-media{\n                padding:15%; /* پدینگ کمی کمتر در موبایل برای وضوح بهتر */\n            }\n\n            .beauty-product-title{\n                font-size:14px;\n                min-height:46px;\n            }\n        }\n    </style>\n    <?php\n\n    wp_reset_postdata();\n    return ob_get_clean();\n});\n','','global',0,10,1,'2026-07-05 11:43:01',1,NULL),(6,'beauty_header_actions','','/**\n * Shortcode: [beauty_header_actions]\n * FINAL FIX\n */\n\nremove_shortcode(\'beauty_header_actions\');\n\nadd_shortcode(\'beauty_header_actions\', function () {\n\n    if (!class_exists(\'WooCommerce\')) {\n        return \'\';\n    }\n\n    $account_url = wc_get_page_permalink(\'myaccount\');\n    $cart_url    = wc_get_cart_url();\n    $cart_count  = WC()->cart ? WC()->cart->get_cart_contents_count() : 0;\n\n    ob_start();\n    ?>\n    \n    <div class=\"beauty-header-actions\">\n\n        <?php if (is_user_logged_in()) : ?>\n            <a href=\"<?php echo esc_url($account_url); ?>\" class=\"beauty-header-action-item\">\n                <span class=\"beauty-header-action-icon\">👤</span>\n                <span class=\"beauty-header-action-text\">حساب کاربری</span>\n            </a>\n        <?php else : ?>\n            <button type=\"button\"\n                    class=\"beauty-header-action-item\"\n                    onclick=\"beautyUIOpenAuth(); return false;\">\n                <span class=\"beauty-header-action-icon\">👤</span>\n                <span class=\"beauty-header-action-text\">ورود | ثبت‌نام</span>\n            </button>\n        <?php endif; ?>\n\n\n        <?php if (is_user_logged_in()) : ?>\n            <a href=\"<?php echo esc_url($cart_url); ?>\" class=\"beauty-header-action-item\">\n                <span class=\"beauty-header-action-icon beauty-cart-icon-wrap\">\n                    🛒\n                    <?php if ($cart_count > 0) : ?>\n                        <span class=\"beauty-header-cart-badge\"><?php echo esc_html($cart_count); ?></span>\n                    <?php endif; ?>\n                </span>\n                <span class=\"beauty-header-action-text\">سبد خرید</span>\n            </a>\n        <?php else : ?>\n            <button type=\"button\"\n                    class=\"beauty-header-action-item\"\n                    onclick=\"beautyUIOpenAuth(); return false;\">\n                <span class=\"beauty-header-action-icon beauty-cart-icon-wrap\">\n                    🛒\n                    <?php if ($cart_count > 0) : ?>\n                        <span class=\"beauty-header-cart-badge\"><?php echo esc_html($cart_count); ?></span>\n                    <?php endif; ?>\n                </span>\n                <span class=\"beauty-header-action-text\">سبد خرید</span>\n            </button>\n        <?php endif; ?>\n\n    </div>\n\n    <style>\n    .beauty-header-actions{\n        display:flex;\n        align-items:center;\n        gap:10px;\n    }\n\n    .beauty-header-action-item{\n        position:relative;\n        display:inline-flex;\n        align-items:center;\n        gap:8px;\n        height:42px;\n        padding:0 14px;\n        border-radius:12px;\n        border:1px solid rgba(0,0,0,.08);\n        background:#fff;\n        color:#111;\n        text-decoration:none !important;\n        cursor:pointer;\n        font-size:13px;\n        font-weight:500;\n    }\n\n    .beauty-header-action-item:hover{\n        background:#f8f8f8;\n    }\n\n    .beauty-header-action-icon{\n        position:relative;\n        display:flex;\n        align-items:center;\n        justify-content:center;\n    }\n\n    .beauty-cart-icon-wrap{\n        position:relative;\n    }\n\n    .beauty-header-cart-badge{\n        position:absolute;\n        top:-8px;\n        right:-10px;\n        min-width:18px;\n        height:18px;\n        padding:0 5px;\n        border-radius:999px;\n        background:#111;\n        color:#fff;\n        font-size:10px;\n        font-weight:700;\n        display:flex;\n        align-items:center;\n        justify-content:center;\n        line-height:1;\n    }\n\n    .beauty-header-action-item button{\n        all:unset;\n    }\n    </style>\n\n    <?php\n    return ob_get_clean();\n});\n','','global',0,10,1,'2026-07-02 15:08:26',1,NULL),(7,'beauty_main_menu','','if (!function_exists(\'beauty_menu_build_tree\')) {\n    function beauty_menu_build_tree($items) {\n        $by_id = [];\n        $tree  = [];\n\n        foreach ($items as $item) {\n            $item->children = [];\n            $by_id[$item->ID] = $item;\n        }\n\n        foreach ($items as $item) {\n            $parent_id = (int) $item->menu_item_parent;\n\n            if ($parent_id && isset($by_id[$parent_id])) {\n                $by_id[$parent_id]->children[] = $item;\n            } else {\n                $tree[] = $item;\n            }\n        }\n\n        return $tree;\n    }\n}\n\nif (!function_exists(\'beauty_menu_chunk_children\')) {\n    function beauty_menu_chunk_children($children, $parts = 2) {\n        $count = count($children);\n\n        if ($count <= 1) {\n            return [$children];\n        }\n\n        $size = (int) ceil($count / $parts);\n        return array_chunk($children, $size);\n    }\n}\n\nadd_shortcode(\'beauty_main_menu\', function () {\n    $menu_obj = wp_get_nav_menu_object(\'main_menu\');\n\n    if (!$menu_obj) {\n        return \'<!-- Menu not found: main_menu -->\';\n    }\n\n    $items = wp_get_nav_menu_items($menu_obj->term_id);\n\n    if (empty($items) || !is_array($items)) {\n        return \'\';\n    }\n\n    $tree = beauty_menu_build_tree($items);\n\n    /*\n     * اینجا عکس‌ها را عوض کن:\n     * کلید = عنوان آیتم سطح اول منو\n     * مقدار = لینک عکس\n     */\n    $promo_images = [\n        \'مراقبت پوست\'   => \'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?q=80&w=1200&auto=format&fit=crop\',\n        \'ضدآفتاب\'       => \'https://images.unsplash.com/photo-1506152983158-b4a74a01c721?q=80&w=1200&auto=format&fit=crop\',\n        \'برندها\'        => \'https://images.unsplash.com/photo-1527799820374-dcf8d9d4a3d4?q=80&w=1200&auto=format&fit=crop\',\n        \'بهداشت شخصی\'   => \'https://images.unsplash.com/photo-1587017539504-67cfbddac569?q=80&w=1200&auto=format&fit=crop\',\n    ];\n\n    ob_start();\n    ?>\n    <div class=\"beauty-menu\" id=\"beautyMenu\">\n        <div class=\"beauty-menu__desktop\">\n            <nav class=\"beauty-menu__nav\" aria-label=\"منوی اصلی\">\n                <ul class=\"beauty-wp-menu\">\n                    <?php foreach ($tree as $item) : ?>\n                        <li class=\"beauty-wp-item <?php echo !empty($item->children) ? \'has-children\' : \'\'; ?>\">\n                            <a class=\"beauty-menu__trigger\" href=\"<?php echo esc_url($item->url); ?>\">\n                                <span><?php echo esc_html($item->title); ?></span>\n                            </a>\n\n                            <?php if (!empty($item->children)) : ?>\n                                <?php\n                                $chunks = beauty_menu_chunk_children($item->children, 2);\n                                $feature_image = $promo_images[$item->title] ?? \'\';\n                                ?>\n                                <div class=\"beauty-menu__mega\">\n                                    <div class=\"beauty-menu__mega-inner\">\n                                        <a\n                                            class=\"beauty-menu__feature\"\n                                            href=\"<?php echo esc_url($item->url); ?>\"\n                                            style=\"<?php echo $feature_image ? \'background-image:url(\\\'\' . esc_url($feature_image) . \'\\\');\' : \'\'; ?>\"\n                                        >\n                                            <span class=\"beauty-menu__feature-label\">مجموعه</span>\n                                            <strong><?php echo esc_html($item->title); ?></strong>\n                                            <small>مرور سریع زیر‌دسته‌ها و محصولات مرتبط</small>\n                                        </a>\n\n                                        <div class=\"beauty-menu__links-block\">\n                                            <h4>زیر دسته‌ها</h4>\n                                            <div class=\"beauty-menu__links-grid <?php echo count($chunks) > 1 ? \'is-two\' : \'is-one\'; ?>\">\n                                                <?php foreach ($chunks as $chunk) : ?>\n                                                    <div class=\"beauty-menu__col\">\n                                                        <?php foreach ($chunk as $child) : ?>\n                                                            <a href=\"<?php echo esc_url($child->url); ?>\">\n                                                                <?php echo esc_html($child->title); ?>\n                                                            </a>\n                                                        <?php endforeach; ?>\n                                                    </div>\n                                                <?php endforeach; ?>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            <?php endif; ?>\n                        </li>\n                    <?php endforeach; ?>\n                </ul>\n            </nav>\n        </div>\n\n        <button class=\"beauty-menu__mobile-btn\" type=\"button\" aria-controls=\"beautyDrawer\" aria-expanded=\"false\" aria-label=\"باز کردن منو\">\n            <span class=\"beauty-menu__mobile-icon\" aria-hidden=\"true\">\n                <span></span>\n                <span></span>\n                <span></span>\n            </span>\n        </button>\n\n        <div class=\"beauty-menu__overlay\" hidden></div>\n\n        <aside class=\"beauty-menu__drawer\" id=\"beautyDrawer\" aria-hidden=\"true\">\n            <div class=\"beauty-menu__drawer-head\">\n                <strong>دسته‌بندی‌ها</strong>\n                <button class=\"beauty-menu__close\" type=\"button\" aria-label=\"بستن منو\">×</button>\n            </div>\n\n            <div class=\"beauty-menu__drawer-links\">\n                <?php foreach ($tree as $item) : ?>\n                    <?php if (!empty($item->children)) : ?>\n                        <details class=\"beauty-menu__group\">\n                            <summary>\n                                <span><?php echo esc_html($item->title); ?></span>\n                            </summary>\n\n                            <div class=\"beauty-menu__panel\">\n                                <a class=\"beauty-menu__all-link\" href=\"<?php echo esc_url($item->url); ?>\">\n                                    همه موارد <?php echo esc_html($item->title); ?>\n                                </a>\n\n                                <?php foreach ($item->children as $child) : ?>\n                                    <a href=\"<?php echo esc_url($child->url); ?>\">\n                                        <?php echo esc_html($child->title); ?>\n                                    </a>\n                                <?php endforeach; ?>\n                            </div>\n                        </details>\n                    <?php else : ?>\n                        <a class=\"beauty-menu__drawer-toplink\" href=\"<?php echo esc_url($item->url); ?>\">\n                            <?php echo esc_html($item->title); ?>\n                        </a>\n                    <?php endif; ?>\n                <?php endforeach; ?>\n            </div>\n        </aside>\n    </div>\n\n    <style>\n    .beauty-menu{\n        position:relative;\n        z-index:999999;\n        font-family:inherit;\n        overflow:visible;\n    }\n\n    .beauty-menu,\n    .beauty-menu *{\n        box-sizing:border-box;\n    }\n\n    .beauty-menu__desktop,\n    .beauty-menu__nav,\n    .beauty-wp-menu,\n    .beauty-wp-item{\n        overflow:visible;\n    }\n\n    .beauty-menu__desktop{\n        display:flex;\n        align-items:center;\n        gap:22px;\n        position:relative;\n    }\n\n    .beauty-menu__nav{\n        width:100%;\n    }\n\n    .beauty-wp-menu{\n        display:flex;\n        align-items:center;\n        gap:8px;\n        list-style:none;\n        margin:0;\n        padding:0;\n        flex-wrap:wrap;\n    }\n\n    .beauty-wp-item{\n        position:relative;\n    }\n\n    .beauty-menu__trigger{\n        position:relative;\n        display:inline-flex;\n        align-items:center;\n        padding:10px 12px;\n        text-decoration:none;\n        color:#111;\n        font-size:14px;\n        font-weight:600;\n        border-radius:12px;\n        transition:color .25s ease;\n        background:transparent !important;\n    }\n\n    .beauty-menu__trigger:hover{\n        background:transparent !important;\n    }\n\n    .beauty-menu__trigger span{\n        position:relative;\n        display:inline-block;\n        padding-bottom:2px;\n    }\n\n    .beauty-menu__trigger span::after{\n        content:\"\";\n        position:absolute;\n        right:0;\n        bottom:-3px;\n        width:0;\n        height:1px;\n        background:#111;\n        transition:width .22s ease;\n    }\n\n    .beauty-wp-item:hover .beauty-menu__trigger span::after,\n    .beauty-wp-item:focus-within .beauty-menu__trigger span::after{\n        width:100%;\n    }\n\n    .beauty-menu__mega{\n        position:absolute;\n        top:calc(100% + 14px);\n        left:50%;\n        transform:translateX(-50%) translateY(10px);\n        width:min(1180px, 96vw);\n        opacity:0;\n        visibility:hidden;\n        transition:all .22s ease;\n        pointer-events:none;\n        background:#fff;\n        border:1px solid rgba(0,0,0,.06);\n        border-radius:24px;\n        box-shadow:none !important;\n        overflow:hidden;\n        z-index:999999;\n    }\n\n    .beauty-wp-item:hover > .beauty-menu__mega,\n    .beauty-wp-item:focus-within > .beauty-menu__mega{\n        opacity:1;\n        visibility:visible;\n        transform:translateX(-50%) translateY(0);\n        pointer-events:auto;\n    }\n\n    .beauty-menu__mega-inner{\n        display:grid;\n        grid-template-columns:.95fr 1.35fr;\n        min-height:280px;\n    }\n\n    .beauty-menu__feature{\n        display:flex;\n        flex-direction:column;\n        justify-content:flex-end;\n        gap:10px;\n        padding:24px;\n        text-decoration:none;\n        color:#111;\n        background:\n            linear-gradient(180deg, rgba(255,255,255,.04) 0%, rgba(255,255,255,.82) 100%),\n            center/cover no-repeat;\n        position:relative;\n        box-shadow:none !important;\n    }\n\n    .beauty-menu__feature::before{\n        content:\"\";\n        position:absolute;\n        inset:0;\n        background-image:inherit;\n        background-size:cover;\n        background-position:center;\n        filter:saturate(1.02);\n        z-index:-1;\n    }\n\n    .beauty-menu__feature-label{\n        display:inline-flex;\n        width:max-content;\n        padding:5px 10px;\n        border-radius:999px;\n        background:#111;\n        color:#fff;\n        font-size:11px;\n        font-weight:700;\n    }\n\n    .beauty-menu__feature strong{\n        display:block;\n        font-size:20px;\n        line-height:1.4;\n    }\n\n    .beauty-menu__feature small{\n        display:block;\n        color:#666;\n        font-size:13px;\n        line-height:1.8;\n    }\n\n    .beauty-menu__links-block{\n        padding:22px 22px 18px;\n    }\n\n    .beauty-menu__links-block h4{\n        margin:0 0 14px;\n        font-size:12px;\n        font-weight:800;\n        color:#7a7a7a;\n    }\n\n    .beauty-menu__links-grid{\n        display:grid;\n        gap:12px;\n    }\n\n    .beauty-menu__links-grid.is-two{\n        grid-template-columns:repeat(2, minmax(0, 1fr));\n    }\n\n    .beauty-menu__links-grid.is-one{\n        grid-template-columns:1fr;\n    }\n\n    .beauty-menu__col{\n        display:grid;\n        gap:8px;\n        align-content:start;\n    }\n\n    .beauty-menu__col a{\n        display:block;\n        padding:10px 12px;\n        border-radius:14px;\n        color:#111;\n        text-decoration:none;\n        font-size:14px;\n        line-height:1.45;\n        background:#fafafa;\n        transition:background .2s ease, transform .2s ease;\n    }\n\n    .beauty-menu__col a:hover{\n        background:#f1f1f1;\n        transform:translateX(-2px);\n    }\n\n    /* Mobile button: icon only, transparent */\n    .beauty-menu__mobile-btn{\n        display:none;\n        width:auto;\n        height:auto;\n        padding:0;\n        margin:0;\n        border:0;\n        background:transparent !important;\n        color:#111;\n        cursor:pointer;\n        -webkit-tap-highlight-color:transparent;\n        box-shadow:none !important;\n    }\n\n    .beauty-menu__mobile-icon{\n        display:inline-flex;\n        flex-direction:column;\n        justify-content:center;\n        gap:4px;\n        width:34px;\n        height:34px;\n        background:transparent !important;\n        box-shadow:none !important;\n    }\n\n    .beauty-menu__mobile-icon span{\n        display:block;\n        width:20px;\n        height:2px;\n        border-radius:999px;\n        background:#111;\n    }\n\n    .beauty-menu__overlay{\n        position:fixed;\n        inset:0;\n        background:rgba(0,0,0,.28);\n        opacity:0;\n        visibility:hidden;\n        transition:opacity .25s ease, visibility .25s ease;\n        z-index:999998;\n    }\n\n    .beauty-menu__drawer{\n        position:fixed;\n        top:0;\n        right:0;\n        width:min(88vw, 390px);\n        height:100vh;\n        background:#fff;\n        box-shadow:none !important;\n        transform:translateX(105%);\n        transition:transform .28s cubic-bezier(.22,1,.36,1);\n        z-index:999999;\n        overflow:auto;\n        padding:16px 16px 24px;\n    }\n\n    .beauty-menu.is-open .beauty-menu__overlay{\n        opacity:1;\n        visibility:visible;\n    }\n\n    .beauty-menu.is-open .beauty-menu__drawer{\n        transform:translateX(0);\n    }\n\n    .beauty-menu__drawer-head{\n        display:flex;\n        align-items:center;\n        justify-content:space-between;\n        gap:12px;\n        padding-bottom:12px;\n        margin-bottom:14px;\n        border-bottom:1px solid rgba(0,0,0,.08);\n        direction:rtl;\n        text-align:right;\n    }\n\n    .beauty-menu__drawer-head strong{\n        font-size:16px;\n        font-weight:800;\n        color:#111;\n        text-align:right;\n    }\n\n    .beauty-menu__close{\n        width:38px;\n        height:38px;\n        border:0;\n        border-radius:12px;\n        background:#f3f3f3;\n        color:#111;\n        font-size:24px;\n        line-height:1;\n        cursor:pointer;\n        box-shadow:none !important;\n    }\n\n    .beauty-menu__drawer-links{\n        display:grid;\n        gap:0;\n        text-align:right;\n        direction:rtl;\n    }\n\n    .beauty-menu__drawer-toplink{\n        display:flex;\n        align-items:center;\n        justify-content:flex-end;\n        min-height:48px;\n        padding:10px 12px;\n        border-radius:0;\n        background:#fff;\n        color:#111;\n        text-decoration:none;\n        font-size:13px;\n        font-weight:700;\n        text-align:right;\n        direction:rtl;\n        border-bottom:1px solid rgba(0,0,0,.08);\n    }\n\n    .beauty-menu__group{\n        border-bottom:1px solid rgba(0,0,0,.08);\n        padding:10px 0;\n        direction:rtl;\n        text-align:right;\n    }\n\n    .beauty-menu__group summary{\n        list-style:none;\n        cursor:pointer;\n        display:flex;\n        align-items:center;\n        justify-content:space-between;\n        gap:10px;\n        font-size:14px;\n        font-weight:800;\n        color:#111;\n        outline:none;\n        direction:rtl;\n        text-align:right;\n    }\n\n    .beauty-menu__group summary::-webkit-details-marker{\n        display:none;\n    }\n\n    .beauty-menu__group summary::after{\n        content:\"›\";\n        font-size:24px;\n        line-height:1;\n        color:#666;\n        transform:rotate(90deg);\n        transition:transform .2s ease;\n    }\n\n    .beauty-menu__group[open] summary::after{\n        transform:rotate(-90deg);\n    }\n\n    .beauty-menu__panel{\n        display:grid;\n        gap:8px;\n        padding:12px 0 2px;\n        direction:rtl;\n        text-align:right;\n    }\n\n    .beauty-menu__all-link,\n    .beauty-menu__panel a{\n        display:flex;\n        align-items:center;\n        justify-content:flex-end;\n        padding:10px 12px;\n        border-radius:12px;\n        background:#fafafa;\n        color:#111;\n        text-decoration:none;\n        font-size:13px;\n        line-height:1.5;\n        text-align:right;\n        direction:rtl;\n    }\n\n    .beauty-menu__panel a:hover,\n    .beauty-menu__all-link:hover{\n        background:#f1f1f1;\n    }\n\n    @media (max-width: 767px){\n        .beauty-menu__desktop{\n            display:none;\n        }\n\n        .beauty-menu__mobile-btn{\n            display:inline-flex;\n            align-items:center;\n            justify-content:center;\n        }\n    }\n    </style>\n\n    <script>\n    document.addEventListener(\'DOMContentLoaded\', function () {\n        const menu = document.getElementById(\'beautyMenu\');\n        if (!menu) return;\n\n        const btn = menu.querySelector(\'.beauty-menu__mobile-btn\');\n        const closeBtn = menu.querySelector(\'.beauty-menu__close\');\n        const overlay = menu.querySelector(\'.beauty-menu__overlay\');\n\n        const openMenu = () => {\n            menu.classList.add(\'is-open\');\n            if (btn) btn.setAttribute(\'aria-expanded\', \'true\');\n            const drawer = menu.querySelector(\'.beauty-menu__drawer\');\n            if (drawer) drawer.setAttribute(\'aria-hidden\', \'false\');\n            if (overlay) overlay.hidden = false;\n        };\n\n        const closeMenu = () => {\n            menu.classList.remove(\'is-open\');\n            if (btn) btn.setAttribute(\'aria-expanded\', \'false\');\n            const drawer = menu.querySelector(\'.beauty-menu__drawer\');\n            if (drawer) drawer.setAttribute(\'aria-hidden\', \'true\');\n            if (overlay) {\n                setTimeout(() => {\n                    if (!menu.classList.contains(\'is-open\')) overlay.hidden = true;\n                }, 250);\n            }\n        };\n\n        btn?.addEventListener(\'click\', function () {\n            if (menu.classList.contains(\'is-open\')) closeMenu();\n            else openMenu();\n        });\n\n        closeBtn?.addEventListener(\'click\', closeMenu);\n        overlay?.addEventListener(\'click\', closeMenu);\n\n        document.addEventListener(\'keydown\', function (e) {\n            if (e.key === \'Escape\') closeMenu();\n        });\n\n        menu.querySelectorAll(\'a\').forEach(link => {\n            link.addEventListener(\'click\', () => {\n                if (window.innerWidth <= 767) closeMenu();\n            });\n        });\n    });\n    </script>\n    <?php\n\n    return ob_get_clean();\n});','','global',0,10,1,'2026-06-13 21:20:28',1,NULL),(8,'[beauty_ajax_search]','','add_action(\'wp_ajax_beauty_ajax_search_products\', \'beauty_ajax_search_products\');\nadd_action(\'wp_ajax_nopriv_beauty_ajax_search_products\', \'beauty_ajax_search_products\');\n\nfunction beauty_ajax_search_products() {\n    check_ajax_referer(\'beauty_ajax_search_nonce\', \'nonce\');\n\n    if (!class_exists(\'WooCommerce\')) {\n        wp_send_json_error([\'message\' => \'WooCommerce not active\']);\n    }\n\n    $term = isset($_POST[\'term\']) ? sanitize_text_field(wp_unslash($_POST[\'term\'])) : \'\';\n    $term = trim($term);\n\n    if ($term === \'\') {\n        wp_send_json_success([\'items\' => []]);\n    }\n\n    $query = new WP_Query([\n        \'post_type\'           => \'product\',\n        \'post_status\'         => \'publish\',\n        \'s\'                   => $term,\n        \'posts_per_page\'      => 8,\n        \'ignore_sticky_posts\' => true,\n    ]);\n\n    $items = [];\n\n    if ($query->have_posts()) {\n        while ($query->have_posts()) {\n            $query->the_post();\n\n            $product = wc_get_product(get_the_ID());\n            if (!$product) {\n                continue;\n            }\n\n            $items[] = [\n                \'title\' => get_the_title(),\n                \'url\'   => get_permalink(),\n                \'image\' => get_the_post_thumbnail_url(get_the_ID(), \'woocommerce_thumbnail\') ?: wc_placeholder_img_src(\'woocommerce_thumbnail\'),\n                \'price\' => $product->get_price_html(),\n            ];\n        }\n        wp_reset_postdata();\n    }\n\n    wp_send_json_success([\'items\' => $items]);\n}\n\nadd_shortcode(\'beauty_ajax_search\', function ($atts) {\n    $atts = shortcode_atts([\n        \'placeholder\' => \'جستجوی محصولات، برندها...\',\n    ], $atts, \'beauty_ajax_search\');\n\n    $nonce = wp_create_nonce(\'beauty_ajax_search_nonce\');\n    $uid   = wp_unique_id(\'beauty_search_\');\n\n    ob_start();\n    ?>\n    <div class=\"beauty-search-wrap\" id=\"<?php echo esc_attr($uid); ?>\" data-nonce=\"<?php echo esc_attr($nonce); ?>\">\n        <div class=\"beauty-search-bar\" role=\"search\" aria-label=\"جستجوی محصولات\">\n            <span class=\"beauty-search-icon\" aria-hidden=\"true\">\n                <svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n                    <path d=\"M21 21L16.65 16.65\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n                    <circle cx=\"11\" cy=\"11\" r=\"7\" stroke=\"currentColor\" stroke-width=\"2\"/>\n                </svg>\n            </span>\n\n            <input\n                type=\"search\"\n                class=\"beauty-search-input\"\n                placeholder=\"<?php echo esc_attr($atts[\'placeholder\']); ?>\"\n                autocomplete=\"off\"\n                inputmode=\"search\"\n            />\n        </div>\n\n        <div class=\"beauty-search-dropdown\" hidden></div>\n\n        <div class=\"beauty-search-modal\" aria-hidden=\"true\">\n            <div class=\"beauty-search-modal__overlay\"></div>\n\n            <div class=\"beauty-search-modal__panel\" role=\"dialog\" aria-modal=\"true\" aria-label=\"جستجوی محصولات\">\n                <div class=\"beauty-search-modal__head\">\n                    <span>جستجو</span>\n                    <button type=\"button\" class=\"beauty-search-modal__close\" aria-label=\"بستن\">×</button>\n                </div>\n\n                <div class=\"beauty-search-modal__bar\">\n                    <span class=\"beauty-search-icon\" aria-hidden=\"true\">\n                        <svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n                            <path d=\"M21 21L16.65 16.65\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n                            <circle cx=\"11\" cy=\"11\" r=\"7\" stroke=\"currentColor\" stroke-width=\"2\"/>\n                        </svg>\n                    </span>\n\n                    <input\n                        type=\"search\"\n                        class=\"beauty-search-input-mobile\"\n                        placeholder=\"<?php echo esc_attr($atts[\'placeholder\']); ?>\"\n                        autocomplete=\"off\"\n                        inputmode=\"search\"\n                    />\n                </div>\n\n                <div class=\"beauty-search-modal__results\"></div>\n            </div>\n        </div>\n    </div>\n\n    <style>\n        .beauty-search-wrap{\n            position:relative;\n            direction:rtl;\n            font-family:inherit;\n            color:#262626;\n            z-index:9999;\n        }\n\n        .beauty-search-bar{\n            display:flex;\n            align-items:center;\n            gap:12px;\n            height:44px;\n            padding:0 14px;\n            border:1px solid #E7E7E7;\n            border-radius:12px;\n            background:#fff;\n            box-sizing:border-box;\n            transition:border-color .2s ease, box-shadow .2s ease;\n            cursor:text;\n        }\n\n        .beauty-search-bar:focus-within{\n            border-color:#d7d7d7;\n            box-shadow:0 6px 20px rgba(0,0,0,.04);\n        }\n\n        .beauty-search-icon{\n            display:inline-flex;\n            align-items:center;\n            justify-content:center;\n            color:#262626;\n            flex:0 0 auto;\n        }\n\n        .beauty-search-input,\n        .beauty-search-input-mobile{\n            width:100%;\n            border:0 !important;\n            outline:none !important;\n            background:transparent !important;\n            color:#262626;\n            font-size:14px;\n            height:100%;\n            padding:0;\n            margin:0;\n            font-family:inherit;\n            direction:rtl;\n            text-align:right;\n            box-shadow:none !important;\n        }\n\n        .beauty-search-input::placeholder,\n        .beauty-search-input-mobile::placeholder{\n            color:#9b9b9b;\n        }\n\n        .beauty-search-dropdown{\n            position:absolute;\n            top:calc(100% + 10px);\n            right:0;\n            width:100%;\n            background:#fff;\n            border:1px solid #E7E7E7;\n            border-radius:16px;\n            box-shadow:0 18px 50px rgba(0,0,0,.08);\n            overflow:hidden;\n            z-index:99999;\n        }\n\n        .beauty-search-results{\n            display:grid;\n            gap:0;\n            max-height:420px;\n            overflow:auto;\n        }\n\n        .beauty-search-result{\n            display:grid;\n            grid-template-columns:56px 1fr;\n            gap:12px;\n            align-items:center;\n            padding:12px 14px;\n            text-decoration:none;\n            color:#111;\n            border-bottom:1px solid rgba(0,0,0,.05);\n            transition:background .2s ease;\n        }\n\n        .beauty-search-result:hover{\n            background:#f8f8f8;\n        }\n\n        .beauty-search-result:last-child{\n            border-bottom:0;\n        }\n\n        .beauty-search-thumb{\n            width:56px;\n            height:56px;\n            border-radius:14px;\n            object-fit:cover;\n            background:#f4f4f4;\n        }\n\n        .beauty-search-title{\n            font-size:14px;\n            line-height:1.7;\n            font-weight:700;\n            margin:0 0 4px;\n            color:#111;\n        }\n\n        .beauty-search-price{\n            font-size:13px;\n            line-height:1.5;\n            color:#555;\n            font-weight:600;\n        }\n\n        .beauty-search-empty,\n        .beauty-search-loading{\n            padding:16px 14px;\n            font-size:13px;\n            color:#777;\n            text-align:right;\n        }\n\n        /* Modal */\n        .beauty-search-modal{\n            position:fixed;\n            inset:0;\n            z-index:100000;\n            opacity:0;\n            visibility:hidden;\n            pointer-events:none;\n            transition:opacity .22s ease, visibility .22s ease;\n        }\n\n        .beauty-search-modal.is-open{\n            opacity:1;\n            visibility:visible;\n            pointer-events:auto;\n        }\n\n        .beauty-search-modal__overlay{\n            position:absolute;\n            inset:0;\n            background:rgba(0,0,0,.35);\n        }\n\n        .beauty-search-modal__panel{\n            position:absolute;\n            top:0;\n            left:0;\n            right:0;\n            background:#fff;\n            border-radius:0 0 24px 24px;\n            padding:16px;\n            box-shadow:0 18px 50px rgba(0,0,0,.12);\n            transform:translateY(-12px);\n            transition:transform .22s cubic-bezier(.22,1,.36,1);\n        }\n\n        .beauty-search-modal.is-open .beauty-search-modal__panel{\n            transform:translateY(0);\n        }\n\n        .beauty-search-modal__head{\n            display:flex;\n            align-items:center;\n            justify-content:space-between;\n            margin-bottom:14px;\n            direction:rtl;\n            color:#111;\n            font-size:15px;\n            font-weight:800;\n        }\n\n        .beauty-search-modal__close{\n            width:38px;\n            height:38px;\n            border:0;\n            border-radius:12px;\n            background:#f3f3f3;\n            color:#111;\n            font-size:24px;\n            line-height:1;\n            cursor:pointer;\n        }\n\n        .beauty-search-modal__bar{\n            display:flex;\n            align-items:center;\n            gap:12px;\n            height:44px;\n            padding:0 14px;\n            border:1px solid #E7E7E7;\n            border-radius:12px;\n            background:#fff;\n            box-sizing:border-box;\n            margin-bottom:14px;\n        }\n\n        .beauty-search-modal__results{\n            max-height:calc(100vh - 170px);\n            overflow:auto;\n            border-top:1px solid rgba(0,0,0,.05);\n        }\n\n        /* Desktop / Mobile behavior */\n        @media (max-width:767px){\n            .beauty-search-dropdown{\n                display:none !important;\n            }\n\n            .beauty-search-bar{\n                cursor:pointer;\n            }\n\n            .beauty-search-input{\n                pointer-events:none;\n            }\n        }\n\n        @media (min-width:768px){\n            .beauty-search-modal{\n                display:none !important;\n            }\n        }\n    </style>\n\n    <script>\n    (function(){\n        const root = document.getElementById(\'<?php echo esc_js($uid); ?>\');\n        if (!root) return;\n\n        const nonce = root.getAttribute(\'data-nonce\');\n        const desktopBar = root.querySelector(\'.beauty-search-bar\');\n        const desktopInput = root.querySelector(\'.beauty-search-input\');\n        const dropdown = root.querySelector(\'.beauty-search-dropdown\');\n        const modal = root.querySelector(\'.beauty-search-modal\');\n        const modalOverlay = root.querySelector(\'.beauty-search-modal__overlay\');\n        const modalClose = root.querySelector(\'.beauty-search-modal__close\');\n        const mobileInput = root.querySelector(\'.beauty-search-input-mobile\');\n        const modalResults = root.querySelector(\'.beauty-search-modal__results\');\n\n        let timer = null;\n        let controller = null;\n\n        function isMobile(){\n            return window.matchMedia(\'(max-width: 767px)\').matches;\n        }\n\n        function escapeHtml(str){\n            const div = document.createElement(\'div\');\n            div.textContent = str ?? \'\';\n            return div.innerHTML;\n        }\n\n        function openModal(){\n            modal.classList.add(\'is-open\');\n            modal.setAttribute(\'aria-hidden\', \'false\');\n            setTimeout(() => mobileInput.focus(), 50);\n            document.body.style.overflow = \'hidden\';\n        }\n\n        function closeModal(){\n            modal.classList.remove(\'is-open\');\n            modal.setAttribute(\'aria-hidden\', \'true\');\n            document.body.style.overflow = \'\';\n            mobileInput.value = \'\';\n            modalResults.innerHTML = \'\';\n        }\n\n        function renderResults(items, target){\n            if (!items || !items.length) {\n                target.innerHTML = \'<div class=\"beauty-search-empty\">محصولی پیدا نشد.</div>\';\n                return;\n            }\n\n            target.innerHTML = `\n                <div class=\"beauty-search-results\">\n                    ${items.map(item => `\n                        <a class=\"beauty-search-result\" href=\"${item.url}\">\n                            <img class=\"beauty-search-thumb\" src=\"${item.image}\" alt=\"${escapeHtml(item.title)}\">\n                            <div class=\"beauty-search-meta\">\n                                <div class=\"beauty-search-title\">${escapeHtml(item.title)}</div>\n                                <div class=\"beauty-search-price\">${item.price || \'\'}</div>\n                            </div>\n                        </a>\n                    `).join(\'\')}\n                </div>\n            `;\n        }\n\n        async function search(term, target){\n            term = (term || \'\').trim();\n\n            if (controller) controller.abort();\n            controller = new AbortController();\n\n            if (!term) {\n                target.innerHTML = \'\';\n                return;\n            }\n\n            target.innerHTML = \'<div class=\"beauty-search-loading\">در حال جستجو...</div>\';\n\n            const form = new FormData();\n            form.append(\'action\', \'beauty_ajax_search_products\');\n            form.append(\'nonce\', nonce);\n            form.append(\'term\', term);\n\n            try{\n                const res = await fetch(\'<?php echo esc_url(admin_url(\'admin-ajax.php\')); ?>\', {\n                    method: \'POST\',\n                    credentials: \'same-origin\',\n                    body: form,\n                    signal: controller.signal\n                });\n\n                const data = await res.json();\n                if (data && data.success) {\n                    renderResults(data.data.items, target);\n                } else {\n                    target.innerHTML = \'<div class=\"beauty-search-empty\">نتیجه‌ای پیدا نشد.</div>\';\n                }\n            } catch (err) {\n                if (err.name !== \'AbortError\') {\n                    target.innerHTML = \'<div class=\"beauty-search-empty\">خطا در جستجو.</div>\';\n                }\n            }\n        }\n\n        function handleDesktopInput(){\n            const val = desktopInput.value;\n            dropdown.hidden = false;\n            search(val, dropdown);\n        }\n\n        function handleMobileInput(){\n            const val = mobileInput.value;\n            search(val, modalResults);\n        }\n\n        desktopInput.addEventListener(\'input\', function(){\n            clearTimeout(timer);\n            timer = setTimeout(handleDesktopInput, 250);\n        });\n\n        desktopInput.addEventListener(\'focus\', function(){\n            if (!isMobile() && desktopInput.value.trim()) {\n                dropdown.hidden = false;\n                search(desktopInput.value, dropdown);\n            }\n        });\n\n        document.addEventListener(\'click\', function(e){\n            if (!root.contains(e.target)) {\n                dropdown.hidden = true;\n            }\n        });\n\n        desktopBar.addEventListener(\'click\', function(){\n            if (isMobile()) {\n                openModal();\n            }\n        });\n\n        desktopInput.addEventListener(\'click\', function(e){\n            if (isMobile()) {\n                e.preventDefault();\n                openModal();\n            }\n        });\n\n        mobileInput.addEventListener(\'input\', function(){\n            clearTimeout(timer);\n            timer = setTimeout(handleMobileInput, 250);\n        });\n\n        modalOverlay.addEventListener(\'click\', closeModal);\n        modalClose.addEventListener(\'click\', closeModal);\n\n        document.addEventListener(\'keydown\', function(e){\n            if (e.key === \'Escape\' && modal.classList.contains(\'is-open\')) {\n                closeModal();\n            }\n        });\n\n        // اگر صفحه ریسایز شد\n        window.addEventListener(\'resize\', function(){\n            if (!isMobile()) {\n                closeModal();\n            }\n        });\n    })();\n    </script>\n    <?php\n\n    return ob_get_clean();\n});','','global',0,10,-1,'2026-06-20 21:15:26',1,NULL),(10,'beauty_ajax_search_products','','if (!function_exists(\'beauty_search_box_search_handler_v3\')) {\n    add_action(\'wp_ajax_beauty_search_box_search_v3\', \'beauty_search_box_search_handler_v3\');\n    add_action(\'wp_ajax_nopriv_beauty_search_box_search_v3\', \'beauty_search_box_search_handler_v3\');\n\n    function beauty_search_box_search_handler_v3() {\n        check_ajax_referer(\'beauty_search_box_nonce_v3\', \'nonce\');\n\n        if (!class_exists(\'WooCommerce\')) {\n            wp_send_json_error([\'message\' => \'WooCommerce inactive\'], 400);\n        }\n\n        $term = isset($_POST[\'term\']) ? sanitize_text_field(wp_unslash($_POST[\'term\'])) : \'\';\n        $term = trim($term);\n\n        if ($term === \'\' || mb_strlen($term) < 2) {\n            wp_send_json_success([\'items\' => []]);\n        }\n\n        $query = new WP_Query([\n            \'post_type\'          => \'product\',\n            \'post_status\'        => \'publish\',\n            \'s\'                  => $term,\n            \'posts_per_page\'     => 8,\n            \'ignore_sticky_posts\' => true,\n        ]);\n\n        $items = [];\n\n        if ($query->have_posts()) {\n            while ($query->have_posts()) {\n                $query->the_post();\n\n                $product = wc_get_product(get_the_ID());\n                if (!$product) {\n                    continue;\n                }\n\n                $image = get_the_post_thumbnail_url(get_the_ID(), \'woocommerce_thumbnail\');\n                if (!$image) {\n                    $image = wc_placeholder_img_src(\'woocommerce_thumbnail\');\n                }\n\n                $items[] = [\n                    \'title\' => get_the_title(),\n                    \'url\'   => get_permalink(),\n                    \'image\' => esc_url_raw($image),\n                    \'price\' => $product->get_price_html(),\n                ];\n            }\n            wp_reset_postdata();\n        }\n\n        wp_send_json_success([\'items\' => $items]);\n    }\n}\n\nif (!shortcode_exists(\'beauty_search_box_v3\')) {\n    add_shortcode(\'beauty_search_box_v3\', function ($atts) {\n        if (!class_exists(\'WooCommerce\')) {\n            return \'\';\n        }\n\n        $atts = shortcode_atts([\n            \'placeholder\' => \'جستجوی محصولات، برندها...\',\n        ], $atts, \'beauty_search_box_v3\');\n\n        $uid   = wp_unique_id(\'beauty_search_v3_\');\n        $nonce = wp_create_nonce(\'beauty_search_box_nonce_v3\');\n\n        ob_start();\n        ?>\n        <div class=\"beauty-search-wrap\" id=\"<?php echo esc_attr($uid); ?>\"